INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('buyer''s market', '', '', '[{"en":"In a buyer''s market, suppliers must offer better terms to win contracts.","zh-TW":"在買方市場中，供應商必須提供更好的條款來贏得合約。"},{"en":"Falling house prices signal a buyer''s market in real estate.","zh-TW":"房價下跌預示著房地產市場的買方市場。"}]', 'phrasal verb'),
('capital budget', '', '', '[{"en":"The capital budget allocated $5 million for plant and equipment upgrades.","zh-TW":"資本預算為廠房和設備升級分配了500萬元。"},{"en":"Capital budget decisions require executive approval above a set threshold.","zh-TW":"資本預算決策在超過設定門檻值時需要高管批准。"}]', 'phrasal verb'),
('charge account', '', '', '[{"en":"Corporate clients were offered charge account facilities for monthly billing.","zh-TW":"企業客戶獲得了按月計費的賒帳帳戶設施。"},{"en":"A charge account requires creditworthiness assessment before approval.","zh-TW":"賒帳帳戶在批准之前需要信用狀況評估。"}]', 'phrasal verb'),
('chartered accountant', '', '', '[{"en":"The chartered accountant prepared the statutory accounts.","zh-TW":"特許會計師編製了法定帳目。"},{"en":"A chartered accountant must comply with the standards of their professional body.","zh-TW":"特許會計師必須遵守其專業機構的標準。"}]', 'phrasal verb'),
('conditional offer', '', '', '[{"en":"A conditional offer of employment was made pending reference checks.","zh-TW":"在等待背景調查期間，提出了有條件的聘用要約。"},{"en":"The bank made a conditional offer subject to satisfactory valuation.","zh-TW":"銀行在令人滿意的估值前提下提出了有條件的要約。"}]', 'phrasal verb'),
('confidential information', '', '', '[{"en":"All employees are required to protect confidential information from external parties.","zh-TW":"所有員工都必須保護機密信息不被外部人員獲取。"},{"en":"Sharing confidential information without consent violates the employment contract.","zh-TW":"未經同意分享機密信息違反了勞動合約。"}]', 'phrasal verb'),
('construction contract', '', '', '[{"en":"The construction contract specified completion within 18 months.","zh-TW":"建設合約規定了在18個月內完工。"},{"en":"Disputes arising from construction contracts often proceed to arbitration.","zh-TW":"由建設合約引起的爭議通常進入仲裁程序。"}]', 'phrasal verb'),
('consumer goods', '', '', '[{"en":"The consumer goods sector was resilient despite the economic slowdown.","zh-TW":"儘管經濟放緩，消費品行業仍然保持韌性。"},{"en":"Branded consumer goods command a premium over generic alternatives.","zh-TW":"品牌消費品比非品牌替代品有溢價。"}]', 'phrasal verb'),
('contract negotiation', '', '', '[{"en":"Contract negotiations with the supplier lasted three months.","zh-TW":"與供應商的合約談判持續了三個月。"},{"en":"Experienced legal counsel improves outcomes in complex contract negotiations.","zh-TW":"有經驗的法律顧問改善了複雜合約談判的結果。"}]', 'phrasal verb'),
('counterparty risk', '', '', '[{"en":"Derivatives contracts carry significant counterparty risk if unhedged.","zh-TW":"未對沖的衍生品合約具有顯著的交易對手風險。"},{"en":"Collateral requirements reduce counterparty risk in over-the-counter transactions.","zh-TW":"抵押品要求降低了場外交易中的交易對手風險。"}]', 'phrasal verb'),
('credit analysis', '', '', '[{"en":"A thorough credit analysis is conducted before approving any large loan.","zh-TW":"在批准任何大額貸款之前進行全面的信用分析。"},{"en":"Credit analysis involves reviewing financial statements and cash flow projections.","zh-TW":"信用分析涉及審查財務報表和現金流量預測。"}]', 'phrasal verb'),
('credit default swap', '', '', '[{"en":"Banks use credit default swaps to hedge against borrower default risk.","zh-TW":"銀行使用信貸違約互換對沖借款人違約風險。"},{"en":"Credit default swaps were at the centre of the 2008 financial crisis.","zh-TW":"信貸違約互換是2008年金融危機的核心。"}]', 'phrasal verb'),
('delivery schedule', '', '', '[{"en":"The supplier committed to a weekly delivery schedule for the raw materials.","zh-TW":"供應商承諾按週的交貨時間表交付原材料。"},{"en":"The delivery schedule was revised after a supplier announced capacity constraints.","zh-TW":"在供應商宣布產能限制後，交貨時間表進行了修訂。"}]', 'phrasal verb'),
('distribution rights', '', '', '[{"en":"The company acquired exclusive distribution rights for the product in Asia.","zh-TW":"公司獲得了該產品在亞洲的獨家分銷權。"},{"en":"Distribution rights agreements specify territory, duration, and minimum sales targets.","zh-TW":"分銷權協議規定了地域、期限和最低銷售目標。"}]', 'phrasal verb'),
('domestic market', '', '', '[{"en":"The company focused on the domestic market before considering exports.","zh-TW":"公司在考慮出口之前專注於國內市場。"},{"en":"Strong domestic market performance offset weak international sales.","zh-TW":"強勁的國內市場表現抵消了疲弱的國際銷售。"}]', 'phrasal verb'),
('drawdown facility', '', '', '[{"en":"The project used a drawdown facility to manage construction phase spending.","zh-TW":"項目使用提款設施管理建設階段的支出。"},{"en":"A drawdown facility provides flexible access to funds without interest on unused portions.","zh-TW":"提款設施提供靈活的資金使用，未使用部分不計利息。"}]', 'phrasal verb'),
('effective tax rate', '', '', '[{"en":"The company''s effective tax rate fell to 18% through strategic planning.","zh-TW":"通過戰略規劃，公司的有效稅率降至18%。"},{"en":"Investors compare effective tax rates across companies in different jurisdictions.","zh-TW":"投資者比較不同司法管轄區公司的有效稅率。"}]', 'phrasal verb'),
('executive compensation', '', '', '[{"en":"The executive compensation package included salary, bonus, and stock options.","zh-TW":"高管薪酬方案包括薪資、獎金和股票期權。"},{"en":"Shareholders voted on the executive compensation policy at the annual meeting.","zh-TW":"股東在年會上就高管薪酬政策進行了投票。"}]', 'phrasal verb'),
('exit barrier', '', '', '[{"en":"High exit barriers trapped the company in a loss-making business segment.","zh-TW":"高退出壁壘使公司陷入虧損的業務板塊。"},{"en":"Long-term contracts with suppliers create significant exit barriers.","zh-TW":"與供應商的長期合約創造了顯著的退出壁壘。"}]', 'phrasal verb'),
('financial distress', '', '', '[{"en":"The company entered financial distress after demand collapsed overnight.","zh-TW":"公司在需求一夜崩潰後陷入財務困境。"},{"en":"Financial distress often leads to debt restructuring or bankruptcy proceedings.","zh-TW":"財務困境通常導致債務重組或破產程序。"}]', 'phrasal verb'),
('financial guarantee', '', '', '[{"en":"The subsidiary obtained a financial guarantee from the parent company.","zh-TW":"子公司從母公司獲得了財務擔保。"},{"en":"Banks charge a fee for providing financial guarantees to clients.","zh-TW":"銀行為客戶提供財務擔保收取費用。"}]', 'phrasal verb'),
('fiscal year end', '', '', '[{"en":"All accounts must be reconciled before fiscal year end.","zh-TW":"所有帳戶必須在財政年度末之前對帳。"},{"en":"The company''s fiscal year end is December 31 for all subsidiaries.","zh-TW":"公司所有子公司的財政年度末均為12月31日。"}]', 'phrasal verb'),
('forward integration', '', '', '[{"en":"The manufacturer opened retail stores as part of its forward integration strategy.","zh-TW":"製造商作為其向前整合策略的一部分開設了零售店。"},{"en":"Forward integration allows producers to capture more value closer to the end consumer.","zh-TW":"向前整合允許生產者在更接近最終消費者的地方獲取更多價值。"}]', 'phrasal verb'),
('governance structure', '', '', '[{"en":"A clear governance structure ensures accountability at every level.","zh-TW":"清晰的治理結構確保了各個層面的問責制。"},{"en":"The board approved a new governance structure after the merger.","zh-TW":"董事會在合併後批准了新的治理結構。"}]', 'phrasal verb'),
('headcount reduction', '', '', '[{"en":"The company announced a headcount reduction to cut costs amid declining revenue.","zh-TW":"公司宣布裁員以在收入下降的情況下削減成本。"},{"en":"Natural attrition was used to achieve the headcount reduction target.","zh-TW":"自然減員被用於實現裁員目標。"}]', 'phrasal verb'),
('impairment loss', '', '', '[{"en":"An impairment loss of $15 million was recorded after the subsidiary underperformed.","zh-TW":"在子公司表現不佳後，記錄了1500萬元的減值損失。"},{"en":"Annual impairment tests are required under international accounting standards.","zh-TW":"國際會計準則要求每年進行減值測試。"}]', 'phrasal verb'),
('incentive plan', '', '', '[{"en":"The incentive plan linked bonuses to individual and team performance goals.","zh-TW":"激勵計劃將獎金與個人和團隊績效目標掛鈎。"},{"en":"A well-structured incentive plan improves productivity and reduces turnover.","zh-TW":"結構良好的激勵計劃提高了生產力並降低了員工流動率。"}]', 'phrasal verb'),
('indirect tax', '', '', '[{"en":"Value-added tax is the most common form of indirect tax.","zh-TW":"增值稅是最常見的間接稅形式。"},{"en":"Indirect taxes are regressive as they take a higher proportion of lower incomes.","zh-TW":"間接稅具有累退性，因為它們佔低收入較高的比例。"}]', 'phrasal verb'),
('intellectual property right', '', '', '[{"en":"The company vigorously defends its intellectual property rights in all markets.","zh-TW":"公司在所有市場積極捍衛其知識產權。"},{"en":"Intellectual property right infringement can result in significant legal damages.","zh-TW":"知識產權侵犯可能導致重大法律損害賠償。"}]', 'phrasal verb'),
('labour law', '', '', '[{"en":"The company revised its employment policies to comply with new labour law changes.","zh-TW":"公司修訂了其就業政策以遵守新的勞動法變化。"},{"en":"Labour law protects workers from exploitation and unfair dismissal.","zh-TW":"勞動法保護工人免受剝削和不公平解僱。"}]', 'phrasal verb'),
('land registry', '', '', '[{"en":"The property purchase was completed after registration at the land registry.","zh-TW":"在土地登記處完成登記後，房產購買得以完成。"},{"en":"A land registry search confirms the current owner and any charges.","zh-TW":"土地登記搜索確認了當前所有者和任何產權負擔。"}]', 'phrasal verb'),
('legal compliance', '', '', '[{"en":"The company appointed a legal compliance team to monitor regulatory changes.","zh-TW":"公司指派了一個法律合規團隊來監控法規變化。"},{"en":"Failure to maintain legal compliance can result in fines and reputational damage.","zh-TW":"未能維持法律合規可能導致罰款和聲譽損害。"}]', 'phrasal verb'),
('limited liability', '', '', '[{"en":"Shareholders enjoy limited liability and cannot lose more than their investment.","zh-TW":"股東享有有限責任，不能損失超過其投資額。"},{"en":"The limited liability structure encourages entrepreneurship and risk-taking.","zh-TW":"有限責任結構鼓勵企業家精神和承擔風險。"}]', 'phrasal verb'),
('loss ratio', '', '', '[{"en":"A loss ratio above 100% means the insurer is paying out more than it earns.","zh-TW":"高於100%的賠付率意味著保險公司的賠付超過了其收入。"},{"en":"The insurer reviewed its underwriting criteria after a high loss ratio.","zh-TW":"保險公司在賠付率高之後審查了其承保標準。"}]', 'phrasal verb'),
('manpower planning', '', '', '[{"en":"Manpower planning ensured adequate staffing for the new plant opening.","zh-TW":"人力規劃確保了新工廠開業的充足人員配置。"},{"en":"Effective manpower planning aligns recruitment with business growth projections.","zh-TW":"有效的人力規劃使招募與業務增長預測保持一致。"}]', 'phrasal verb'),
('monthly recurring revenue', '', '', '[{"en":"The SaaS company''s monthly recurring revenue grew 15% quarter over quarter.","zh-TW":"SaaS公司的每月經常性收入環比增長了15%。"},{"en":"Investors value SaaS companies highly based on monthly recurring revenue.","zh-TW":"投資者根據每月經常性收入高度評估SaaS公司的價值。"}]', 'phrasal verb'),
('net revenue', '', '', '[{"en":"Net revenue grew 12% after the new pricing strategy was implemented.","zh-TW":"實施新定價策略後，淨收益增長了12%。"},{"en":"Net revenue provides a more accurate picture of actual sales performance.","zh-TW":"淨收益提供了對實際銷售業績更準確的描述。"}]', 'phrasal verb'),
('open tender', '', '', '[{"en":"The government issued an open tender for the construction of the new highway.","zh-TW":"政府為新公路建設發出了公開招標。"},{"en":"Open tender processes ensure transparency and competitive pricing.","zh-TW":"公開招標流程確保了透明度和競爭性定價。"}]', 'phrasal verb'),
('operating margin', '', '', '[{"en":"The company''s operating margin improved from 12% to 15% after restructuring.","zh-TW":"重組後，公司的營業利潤率從12%提高到了15%。"},{"en":"Analysts compare operating margin across peers to assess efficiency.","zh-TW":"分析師比較同行業的營業利潤率以評估效率。"}]', 'phrasal verb'),
('order backlog', '', '', '[{"en":"A growing order backlog indicated strong demand for the company''s products.","zh-TW":"不斷增長的積壓訂單表明了市場對公司產品的強勁需求。"},{"en":"The company hired additional staff to clear the order backlog quickly.","zh-TW":"公司聘請了額外的人員以快速清除積壓訂單。"}]', 'phrasal verb'),
('outsourced service', '', '', '[{"en":"Payroll processing was moved to an outsourced service to save costs.","zh-TW":"薪資處理被轉移到外包服務以節省成本。"},{"en":"An outsourced service provider must meet the same quality standards as internal teams.","zh-TW":"外包服務提供商必須達到與內部團隊相同的質量標準。"}]', 'phrasal verb'),
('paid-in capital', '', '', '[{"en":"Paid-in capital increased following the rights issue to existing shareholders.","zh-TW":"在向現有股東配股後，已繳入資本增加了。"},{"en":"The paid-in capital account records proceeds from share issuance at par and premium.","zh-TW":"已繳入資本帳戶記錄了面值和溢價發行股份的收益。"}]', 'phrasal verb'),
('patent infringement', '', '', '[{"en":"The company sued a competitor for patent infringement of its key technology.","zh-TW":"公司起訴一家競爭對手侵犯其關鍵技術的專利。"},{"en":"Patent infringement claims can result in injunctions and financial damages.","zh-TW":"專利侵犯索賠可能導致禁令和財務損害賠償。"}]', 'phrasal verb'),
('phased implementation', '', '', '[{"en":"A phased implementation reduced risk by limiting early disruption.","zh-TW":"分階段實施通過限制早期中斷降低了風險。"},{"en":"The software upgrade used a phased implementation to allow staff training.","zh-TW":"軟件升級採用了分階段實施方式，以便員工培訓。"}]', 'phrasal verb'),
('preferential rate', '', '', '[{"en":"Long-standing clients received a preferential rate on all currency transactions.","zh-TW":"長期客戶在所有貨幣交易中獲得了優惠利率。"},{"en":"A preferential rate is used to incentivize early commitment or loyalty.","zh-TW":"優惠費率用於激勵早期承諾或忠誠度。"}]', 'phrasal verb'),
('private placement', '', '', '[{"en":"The company raised $10 million through a private placement to institutional investors.","zh-TW":"公司通過向機構投資者私募配售籌集了1000萬元。"},{"en":"A private placement avoids the costs and disclosure requirements of a public offering.","zh-TW":"私募配售避免了公開募股的成本和披露要求。"}]', 'phrasal verb'),
('refundable deposit', '', '', '[{"en":"A refundable deposit of $500 is required to hold the rental equipment.","zh-TW":"需要500元的可退還押金來預留租用設備。"},{"en":"The refundable deposit was returned in full after the lease term ended.","zh-TW":"租賃期限結束後，可退還押金全額退還了。"}]', 'phrasal verb'),
('registered trademark', '', '', '[{"en":"Using another company''s registered trademark without permission is illegal.","zh-TW":"未經許可使用另一家公司的注冊商標是非法的。"},{"en":"A registered trademark provides exclusive rights to use the mark in commerce.","zh-TW":"注冊商標提供了在商業中使用該標誌的獨家權利。"}]', 'phrasal verb'),
('related party transaction', '', '', '[{"en":"All related party transactions must be disclosed in the financial statements.","zh-TW":"所有關聯方交易必須在財務報表中披露。"},{"en":"The audit committee reviewed the terms of the related party transaction.","zh-TW":"審計委員會審查了關聯方交易的條款。"}]', 'phrasal verb'),
('repurchase agreement', '', '', '[{"en":"The central bank uses repurchase agreements to manage short-term liquidity.","zh-TW":"中央銀行使用回購協議管理短期流動性。"},{"en":"Repurchase agreements are commonly used in money market operations.","zh-TW":"回購協議在貨幣市場操作中被廣泛使用。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('silent partner', '', '', '[{"en":"A silent partner invested $500,000 but had no role in operations.","zh-TW":"隱名合夥人投資了50萬元，但沒有參與運營。"},{"en":"Silent partners share in profits and losses without management responsibilities.","zh-TW":"隱名合夥人在沒有管理責任的情況下分享利潤和損失。"}]', 'phrasal verb'),
('socially responsible investing', '', '', '[{"en":"Pension funds increasingly adopt socially responsible investing principles.","zh-TW":"養老基金越來越多地採用社會責任投資原則。"},{"en":"Socially responsible investing excludes companies in tobacco or weapons industries.","zh-TW":"社會責任投資排除了煙草或武器行業的公司。"}]', 'phrasal verb'),
('standby letter of credit', '', '', '[{"en":"The contractor provided a standby letter of credit as performance security.","zh-TW":"承包商提供了備用信用證作為履約保障。"},{"en":"A standby letter of credit is triggered only when the primary obligation is not met.","zh-TW":"備用信用證僅在主要義務未得到履行時才被啟動。"}]', 'phrasal verb'),
('startup capital', '', '', '[{"en":"The founders raised startup capital from family and angel investors.","zh-TW":"創始人從家人和天使投資者那裏籌集了創業資本。"},{"en":"Startup capital covers initial costs such as equipment, marketing, and working capital.","zh-TW":"創業資本涵蓋初始費用，如設備、行銷和營運資金。"}]', 'phrasal verb'),
('subsidiary rights', '', '', '[{"en":"The publisher sold subsidiary rights for translation into 12 languages.","zh-TW":"出版商出售了翻譯成12種語言的附屬版權。"},{"en":"Subsidiary rights generate additional revenue beyond the primary publication.","zh-TW":"附屬版權在主要出版物之外產生了額外收入。"}]', 'phrasal verb'),
('transaction cost', '', '', '[{"en":"Online trading platforms have significantly reduced transaction costs for investors.","zh-TW":"在線交易平台顯著降低了投資者的交易成本。"},{"en":"Transaction costs include brokerage fees, taxes, and administrative charges.","zh-TW":"交易成本包括經紀費、稅費和行政費用。"}]', 'phrasal verb'),
('Treasury bill', '', '', '[{"en":"Treasury bills are considered risk-free investments in major economies.","zh-TW":"在主要經濟體中，國庫券被視為無風險投資。"},{"en":"Companies hold Treasury bills as part of their cash management strategy.","zh-TW":"公司持有國庫券作為其現金管理策略的一部分。"}]', 'phrasal verb'),
('underfunded pension', '', '', '[{"en":"The company''s underfunded pension liability reached $200 million.","zh-TW":"公司的資金不足養老金負債達到了2億元。"},{"en":"An underfunded pension is a significant risk disclosed in financial statements.","zh-TW":"資金不足的養老金是財務報表中披露的重大風險。"}]', 'phrasal verb'),
('unlisted company', '', '', '[{"en":"Unlisted companies are valued using comparable company or discounted cash flow analysis.","zh-TW":"非上市公司使用可比公司或折現現金流分析進行估值。"},{"en":"Unlisted companies have fewer disclosure requirements than public companies.","zh-TW":"非上市公司比上市公司有更少的披露要求。"}]', 'phrasal verb'),
('zero-based budget', '', '', '[{"en":"The finance director introduced zero-based budgeting to eliminate legacy spending.","zh-TW":"財務總監引入了零基預算以消除遺留支出。"},{"en":"Zero-based budgets prevent the automatic renewal of inefficient expenditures.","zh-TW":"零基預算防止了低效支出的自動更新。"}]', 'phrasal verb'),
('acceptance testing', '', '', '[{"en":"The client conducted acceptance testing before signing off on the software.","zh-TW":"客戶在驗收軟件之前進行了驗收測試。"},{"en":"Acceptance testing ensures the delivered system matches agreed specifications.","zh-TW":"驗收測試確保交付的系統符合商定規格。"}]', 'phrasal verb'),
('accumulated depreciation', '', '', '[{"en":"Accumulated depreciation is subtracted from cost to show net book value.","zh-TW":"累計折舊從成本中扣除以顯示淨帳面價值。"},{"en":"Fully depreciated assets have accumulated depreciation equal to their cost.","zh-TW":"已完全折舊的資產的累計折舊等於其成本。"}]', 'phrasal verb'),
('ad valorem tax', '', '', '[{"en":"Import duties are often structured as an ad valorem tax on the goods'' value.","zh-TW":"進口關稅通常以貨物價值的從價稅形式徵收。"},{"en":"An ad valorem tax rate of 15% applies to all luxury goods imported.","zh-TW":"15%的從價稅率適用於所有進口奢侈品。"}]', 'phrasal verb'),
('administrative expense', '', '', '[{"en":"Administrative expenses were cut by consolidating back-office functions.","zh-TW":"通過整合後台職能降低了行政費用。"},{"en":"Administrative expenses include salaries of management and office overhead.","zh-TW":"行政費用包括管理人員薪資和辦公室間接費用。"}]', 'phrasal verb'),
('advertising budget', '', '', '[{"en":"The advertising budget was increased by 25% to support the product launch.","zh-TW":"廣告預算增加了25%以支持產品發布。"},{"en":"A well-managed advertising budget maximizes return on marketing spend.","zh-TW":"管理良好的廣告預算最大化了行銷支出的回報。"}]', 'phrasal verb'),
('agency relationship', '', '', '[{"en":"In an agency relationship, the agent must act in the principal''s best interest.","zh-TW":"在代理關係中，代理人必須以委托人的最佳利益行事。"},{"en":"Undisclosed agency relationships may give rise to liability for the principal.","zh-TW":"未披露的代理關係可能使委托人承擔責任。"}]', 'phrasal verb'),
('aggregate supply', '', '', '[{"en":"Supply-side reforms aim to increase aggregate supply by reducing production costs.","zh-TW":"供給側改革旨在通過降低生產成本來增加總供給。"},{"en":"Aggregate supply fell after a severe drought damaged agricultural output.","zh-TW":"嚴重乾旱損壞農業產出後，總供給下降了。"}]', 'phrasal verb'),
('antitrust law', '', '', '[{"en":"The merger was blocked by antitrust law authorities on competition grounds.","zh-TW":"合併被反托拉斯法機關以競爭理由阻止了。"},{"en":"Antitrust law promotes fair competition and protects consumer interests.","zh-TW":"反托拉斯法促進公平競爭並保護消費者利益。"}]', 'phrasal verb'),
('arms-length transaction', '', '', '[{"en":"Tax authorities require that related-party dealings be conducted at arms-length.","zh-TW":"稅務機關要求關聯方交易按公平交易原則進行。"},{"en":"An independent valuation confirms the deal is an arms-length transaction.","zh-TW":"獨立估值確認了該交易是公平交易。"}]', 'phrasal verb'),
('authorised capital', '', '', '[{"en":"The company increased its authorised capital to allow a larger share issuance.","zh-TW":"公司增加了其授權資本以允許更大規模的股票發行。"},{"en":"Authorised capital sets an upper limit on the shares a company may sell.","zh-TW":"授權資本設定了公司可出售股份的上限。"}]', 'phrasal verb'),
('automatic renewal', '', '', '[{"en":"The subscription had an automatic renewal clause unless cancelled in advance.","zh-TW":"訂閱有自動續約條款，除非提前取消。"},{"en":"Customers must be notified before an automatic renewal takes effect.","zh-TW":"在自動續約生效之前，必須通知客戶。"}]', 'phrasal verb'),
('backlog of orders', '', '', '[{"en":"The backlog of orders grew to three weeks as production was delayed.","zh-TW":"隨著生產延誤，積壓訂單增長到了三週。"},{"en":"A rising backlog of orders indicates strong demand and potential revenue.","zh-TW":"不斷增長的積壓訂單表明了強勁的需求和潛在收入。"}]', 'phrasal verb'),
('balance sheet analysis', '', '', '[{"en":"Balance sheet analysis revealed significant long-term debt accumulation.","zh-TW":"資產負債表分析揭示了顯著的長期債務積累。"},{"en":"Investors use balance sheet analysis to assess solvency and leverage.","zh-TW":"投資者使用資產負債表分析來評估償付能力和槓桿。"}]', 'phrasal verb'),
('bankruptcy protection', '', '', '[{"en":"The retailer filed for bankruptcy protection to restructure its debts.","zh-TW":"零售商申請破產保護以重組其債務。"},{"en":"Under bankruptcy protection, operations can continue while debts are reorganized.","zh-TW":"在破產保護下，可以在重組債務的同時繼續運營。"}]', 'phrasal verb'),
('boilerplate clause', '', '', '[{"en":"The boilerplate clause on governing law was modified for the jurisdiction.","zh-TW":"管轄法律的標準條款根據司法管轄區進行了修改。"},{"en":"Parties often overlook boilerplate clauses but they can have significant legal impact.","zh-TW":"各方通常忽視標準條款，但它們可能具有重大的法律影響。"}]', 'phrasal verb'),
('bond indenture', '', '', '[{"en":"The bond indenture specified a 6% annual coupon payable semi-annually.","zh-TW":"債券契約規定了每半年支付6%的年票息。"},{"en":"Bondholders can enforce their rights through the provisions of the bond indenture.","zh-TW":"債券持有人可以通過債券契約的條款執行其權利。"}]', 'phrasal verb'),
('breakeven point', '', '', '[{"en":"The breakeven point was reached in the 8th month of operations.","zh-TW":"在運營的第8個月達到了損益兩平點。"},{"en":"Knowing the breakeven point helps set realistic sales targets.","zh-TW":"了解損益兩平點有助於設定現實的銷售目標。"}]', 'phrasal verb'),
('bulk buying', '', '', '[{"en":"Bulk buying reduced per-unit cost and improved margins.","zh-TW":"批量採購降低了每單位成本並改善了利潤率。"},{"en":"The co-operative leverages bulk buying power for its members.","zh-TW":"合作社為其成員利用批量採購能力。"}]', 'phrasal verb'),
('business interruption', '', '', '[{"en":"The flood caused significant business interruption for the warehouse facility.","zh-TW":"洪水對倉庫設施造成了嚴重的業務中斷。"},{"en":"Business interruption insurance covers lost revenue during operational downtime.","zh-TW":"業務中斷保險涵蓋運營停機期間的收入損失。"}]', 'phrasal verb'),
('capital raise', '', '', '[{"en":"The company completed a capital raise of $25 million to fund acquisitions.","zh-TW":"公司完成了2500萬元的融資以資助收購。"},{"en":"A successful capital raise depends on strong investor relations and financials.","zh-TW":"成功的融資依賴於強健的投資者關係和財務狀況。"}]', 'phrasal verb'),
('charter party', '', '', '[{"en":"The charter party specified the freight rate and port of destination.","zh-TW":"租船契約規定了運費和目的地港口。"},{"en":"Disputes under a charter party are typically resolved through maritime arbitration.","zh-TW":"租船契約下的爭議通常通過海事仲裁解決。"}]', 'phrasal verb'),
('collateral agreement', '', '', '[{"en":"A collateral agreement was signed to address the warranty terms separately.","zh-TW":"簽訂了附屬協議以單獨處理保固條款。"},{"en":"Collateral agreements must not contradict the main contract''s provisions.","zh-TW":"附屬協議不得與主合約的條款相抵觸。"}]', 'phrasal verb'),
('commercial lease', '', '', '[{"en":"The startup signed a commercial lease for 500 square meters of office space.","zh-TW":"初創公司為500平方米的辦公空間簽署了商業租賃合約。"},{"en":"Commercial lease terms typically include rent review and break clauses.","zh-TW":"商業租賃條款通常包括租金審查和提前終止條款。"}]', 'phrasal verb'),
('committed facility', '', '', '[{"en":"The company secured a $50 million committed facility from its lending syndicate.","zh-TW":"公司從其貸款銀團獲得了5000萬元的承諾融資額度。"},{"en":"A committed facility provides certainty of funding for strategic investments.","zh-TW":"承諾融資額度為戰略投資提供了資金確定性。"}]', 'phrasal verb'),
('comprehensive insurance', '', '', '[{"en":"The company holds comprehensive insurance covering property, liability, and business interruption.","zh-TW":"公司持有涵蓋財產、責任和業務中斷的綜合保險。"},{"en":"Comprehensive insurance premiums are higher but provide broader protection.","zh-TW":"綜合保險費用較高，但提供更廣泛的保障。"}]', 'phrasal verb'),
('compulsory purchase', '', '', '[{"en":"The property was acquired through a compulsory purchase for road construction.","zh-TW":"房產通過強制購買用於道路建設。"},{"en":"Compensation must be paid at market value in a compulsory purchase.","zh-TW":"強制購買必須按市場價值支付賠償。"}]', 'phrasal verb'),
('consulting fee', '', '', '[{"en":"The consulting fee was based on daily rate plus project deliverables.","zh-TW":"諮詢費基於日費率加上項目可交付成果。"},{"en":"Management consulting fees can represent a significant project cost.","zh-TW":"管理諮詢費可能代表顯著的項目成本。"}]', 'phrasal verb'),
('contract administration', '', '', '[{"en":"Effective contract administration reduces disputes and cost overruns.","zh-TW":"有效的合約管理減少了爭議和成本超支。"},{"en":"Contract administration involves tracking milestones, changes, and payments.","zh-TW":"合約管理涉及追蹤里程碑、變更和付款。"}]', 'phrasal verb'),
('convertible preferred stock', '', '', '[{"en":"Venture investors often receive convertible preferred stock in early-stage deals.","zh-TW":"風險投資者通常在早期交易中獲得可轉換優先股。"},{"en":"Convertible preferred stock offers downside protection with equity upside.","zh-TW":"可轉換優先股提供了下行保護和股權上行潛力。"}]', 'phrasal verb'),
('corporate restructuring', '', '', '[{"en":"The corporate restructuring eliminated 500 positions and closed 3 divisions.","zh-TW":"企業重組消除了500個職位並關閉了3個部門。"},{"en":"Corporate restructuring aims to improve efficiency and long-term profitability.","zh-TW":"企業重組旨在提高效率和長期盈利能力。"}]', 'phrasal verb'),
('credit exposure', '', '', '[{"en":"The bank limited its credit exposure to a single borrower to 10% of capital.","zh-TW":"銀行將對單個借款人的信用敞口限制在資本的10%。"},{"en":"Credit exposure must be monitored across all derivative and lending positions.","zh-TW":"信用敞口必須在所有衍生品和貸款倉位中進行監控。"}]', 'phrasal verb'),
('days payable outstanding', '', '', '[{"en":"Extending days payable outstanding improves short-term cash flow.","zh-TW":"延長應付帳款天數改善了短期現金流。"},{"en":"A high days payable outstanding may indicate cash flow stress.","zh-TW":"高應付帳款天數可能表明現金流壓力。"}]', 'phrasal verb'),
('debt forgiveness', '', '', '[{"en":"The government offered debt forgiveness to small businesses impacted by the crisis.","zh-TW":"政府為受危機影響的小型企業提供了債務減免。"},{"en":"Debt forgiveness may have tax implications for the recipient.","zh-TW":"對接受方而言，債務豁免可能有稅務影響。"}]', 'phrasal verb'),
('derivatives market', '', '', '[{"en":"Companies hedge currency risk by trading in the derivatives market.","zh-TW":"公司通過在衍生品市場交易來對沖貨幣風險。"},{"en":"The derivatives market includes futures, options, and swap contracts.","zh-TW":"衍生品市場包括期貨、期權和互換合約。"}]', 'phrasal verb'),
('development capital', '', '', '[{"en":"The company raised development capital to fund its international expansion.","zh-TW":"公司籌集了發展資本以資助其國際擴張。"},{"en":"Development capital investors typically take a minority equity stake.","zh-TW":"發展資本投資者通常持有少數股權份額。"}]', 'phrasal verb'),
('digital payment', '', '', '[{"en":"Digital payments account for over 70% of consumer transactions in the region.","zh-TW":"數字支付佔該地區消費者交易的70%以上。"},{"en":"The company integrated multiple digital payment options to improve checkout.","zh-TW":"公司整合了多種數字支付選項以改善結帳流程。"}]', 'phrasal verb'),
('dispute settlement', '', '', '[{"en":"The two companies reached a dispute settlement without proceeding to litigation.","zh-TW":"兩家公司在不進行訴訟的情況下達成了爭議解決。"},{"en":"Dispute settlement through mediation is faster and less costly than arbitration.","zh-TW":"通過調解進行爭議解決比仲裁更快且成本更低。"}]', 'phrasal verb'),
('dividend payout ratio', '', '', '[{"en":"The company maintained a dividend payout ratio of 60% of earnings.","zh-TW":"公司維持了60%盈利的股息支付比率。"},{"en":"A high dividend payout ratio signals limited reinvestment in business growth.","zh-TW":"高股息支付比率表明對業務增長的再投資有限。"}]', 'phrasal verb'),
('economic indicator', '', '', '[{"en":"GDP growth and unemployment are key economic indicators watched by investors.","zh-TW":"GDP增長和失業率是投資者關注的關鍵經濟指標。"},{"en":"A leading economic indicator provides early signals of economic direction.","zh-TW":"領先經濟指標提供了經濟走向的早期信號。"}]', 'phrasal verb'),
('elective deferral', '', '', '[{"en":"Employees can increase their elective deferral up to the annual contribution limit.","zh-TW":"員工可以將其自願遞延增加到年度供款上限。"},{"en":"Elective deferrals reduce current taxable income and grow tax-deferred.","zh-TW":"自願遞延降低了當前應稅收入並延稅增長。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('electronic data interchange', '', '', '[{"en":"Electronic data interchange speeds up order processing between trading partners.","zh-TW":"電子數據交換加快了貿易夥伴之間的訂單處理。"},{"en":"Many large retailers require suppliers to use electronic data interchange.","zh-TW":"許多大型零售商要求供應商使用電子數據交換。"}]', 'phrasal verb'),
('employee stock ownership plan', '', '', '[{"en":"An employee stock ownership plan aligns worker interests with company performance.","zh-TW":"員工持股計劃使工人利益與公司績效保持一致。"},{"en":"Employees in the plan benefited from the company''s stock price increase.","zh-TW":"計劃中的員工從公司股價上漲中受益。"}]', 'phrasal verb'),
('end-of-year report', '', '', '[{"en":"The end-of-year report highlighted key achievements and areas for improvement.","zh-TW":"年終報告強調了主要成就和改進領域。"},{"en":"Stakeholders use the end-of-year report to assess overall organizational performance.","zh-TW":"利益相關者使用年終報告評估整體組織績效。"}]', 'phrasal verb'),
('error and omission', '', '', '[{"en":"The consultant took out errors and omissions insurance before providing advice.","zh-TW":"顧問在提供建議之前購買了錯誤與遺漏保險。"},{"en":"An errors and omissions claim can arise from mistakes in professional reports.","zh-TW":"專業報告中的錯誤可能引發錯誤與遺漏索賠。"}]', 'phrasal verb'),
('evaluation criteria', '', '', '[{"en":"The tender documents listed price, quality, and experience as evaluation criteria.","zh-TW":"招標文件將價格、質量和經驗列為評估標準。"},{"en":"Clear evaluation criteria reduce subjectivity in supplier selection.","zh-TW":"清晰的評估標準減少了供應商選擇中的主觀性。"}]', 'phrasal verb'),
('event risk', '', '', '[{"en":"Political instability increased event risk in the emerging market portfolio.","zh-TW":"政治不穩定增加了新興市場投資組合中的事件風險。"},{"en":"Credit downgrades often reflect event risks not anticipated at issuance.","zh-TW":"信用降級通常反映了發行時未預期的事件風險。"}]', 'phrasal verb'),
('exclusive rights', '', '', '[{"en":"The publisher acquired exclusive rights to distribute the series in Asia.","zh-TW":"出版商獲得了在亞洲分銷該系列的獨家權利。"},{"en":"Exclusive rights arrangements restrict competitors from entering the market.","zh-TW":"獨家權利安排限制了競爭對手進入市場。"}]', 'phrasal verb'),
('exit multiple', '', '', '[{"en":"The private equity fund achieved an exit multiple of 3.5 times invested capital.","zh-TW":"私募股權基金實現了3.5倍投入資本的退出倍數。"},{"en":"Exit multiple is a key return metric for private equity investors.","zh-TW":"退出倍數是私募股權投資者的關鍵回報指標。"}]', 'phrasal verb'),
('expense ratio', '', '', '[{"en":"Index funds typically have a much lower expense ratio than active funds.","zh-TW":"指數基金的費用比率通常遠低於主動管理基金。"},{"en":"The expense ratio directly reduces investor returns over time.","zh-TW":"費用比率隨時間推移直接降低了投資者回報。"}]', 'phrasal verb'),
('export financing', '', '', '[{"en":"Export financing allowed the company to offer extended payment terms to buyers.","zh-TW":"出口融資允許公司向買家提供延長的付款條款。"},{"en":"Government export financing agencies support national exporters competitively.","zh-TW":"政府出口融資機構支持本國出口商提高競爭力。"}]', 'phrasal verb'),
('exposure limit', '', '', '[{"en":"The bank set a $20 million exposure limit per borrower.","zh-TW":"銀行為每個借款人設定了2000萬元的敞口限額。"},{"en":"Breach of an exposure limit triggers a mandatory risk reduction.","zh-TW":"突破敞口限額觸發了強制性的風險降低。"}]', 'phrasal verb'),
('factored receivables', '', '', '[{"en":"By using factored receivables, the company converted invoices to immediate cash.","zh-TW":"通過使用保理應收帳款，公司將發票轉換為即時現金。"},{"en":"Factored receivables reduce the book value of outstanding debtors.","zh-TW":"保理應收帳款減少了未付款客戶的帳面價值。"}]', 'phrasal verb'),
('fair value', '', '', '[{"en":"Under fair value accounting, assets are recorded at current market prices.","zh-TW":"在公平價值會計下，資產按當前市場價格記錄。"},{"en":"Fair value adjustments can cause significant income statement volatility.","zh-TW":"公平價值調整可能導致損益表的顯著波動。"}]', 'phrasal verb'),
('financial obligation', '', '', '[{"en":"The company met all its financial obligations despite difficult market conditions.","zh-TW":"儘管市場條件困難，公司履行了所有財務義務。"},{"en":"Failure to meet a financial obligation can trigger cross-default provisions.","zh-TW":"未能履行財務義務可能觸發交叉違約條款。"}]', 'phrasal verb'),
('fixed income security', '', '', '[{"en":"Government bonds are the most common type of fixed income security.","zh-TW":"政府債券是最常見的固定收益證券類型。"},{"en":"Fixed income securities provide predictable returns for conservative investors.","zh-TW":"固定收益證券為保守型投資者提供可預測的回報。"}]', 'phrasal verb'),
('floating charge', '', '', '[{"en":"The bank holds a floating charge over the company''s inventory and receivables.","zh-TW":"銀行對公司的庫存和應收帳款持有浮動押記。"},{"en":"A floating charge crystallizes on insolvency and becomes a fixed charge.","zh-TW":"浮動押記在破產時固化成為固定押記。"}]', 'phrasal verb'),
('flow-through entity', '', '', '[{"en":"Partnerships and LLCs are common examples of flow-through entities.","zh-TW":"合夥企業和有限責任公司是常見的流通實體例子。"},{"en":"A flow-through entity avoids double taxation at the corporate level.","zh-TW":"流通實體避免了在企業層面的雙重課稅。"}]', 'phrasal verb'),
('forward guidance', '', '', '[{"en":"The central bank''s forward guidance indicated rates would remain low for two years.","zh-TW":"中央銀行的前瞻指引表明利率將在兩年內保持低位。"},{"en":"Forward guidance reduces market uncertainty and stabilizes investor expectations.","zh-TW":"前瞻指引減少了市場不確定性並穩定了投資者預期。"}]', 'phrasal verb'),
('freight cost', '', '', '[{"en":"Freight costs increased after fuel prices rose sharply.","zh-TW":"燃料價格急劇上漲後運費增加了。"},{"en":"Freight costs are included in the landed cost of imported goods.","zh-TW":"運費包含在進口商品的到岸成本中。"}]', 'phrasal verb'),
('fund of funds', '', '', '[{"en":"A fund of funds provides diversification across multiple managers.","zh-TW":"基金中的基金在多個管理人之間提供了多元化。"},{"en":"Fund of funds investors pay two layers of management fees.","zh-TW":"基金中的基金投資者支付兩層管理費。"}]', 'phrasal verb'),
('going-private transaction', '', '', '[{"en":"The founder initiated a going-private transaction to gain operational flexibility.","zh-TW":"創始人啟動了私有化交易以獲得運營靈活性。"},{"en":"A going-private transaction requires a premium offer to public shareholders.","zh-TW":"私有化交易需要向公眾股東提出溢價要約。"}]', 'phrasal verb'),
('government bond', '', '', '[{"en":"Government bonds are considered the safest fixed income investments.","zh-TW":"政府債券被視為最安全的固定收益投資。"},{"en":"The yield on government bonds reflects expectations for inflation and growth.","zh-TW":"政府債券的殖利率反映了對通貨膨脹和增長的預期。"}]', 'phrasal verb'),
('impact investing', '', '', '[{"en":"Impact investing targets companies solving environmental and social challenges.","zh-TW":"影響力投資針對解決環境和社會挑戰的公司。"},{"en":"Many institutional investors allocate a portion of assets to impact investing.","zh-TW":"許多機構投資者將部分資產分配到影響力投資。"}]', 'phrasal verb'),
('incremental cost', '', '', '[{"en":"The incremental cost of producing one more batch was $800.","zh-TW":"再生產一批的增量成本為800元。"},{"en":"Pricing decisions should consider incremental cost versus marginal revenue.","zh-TW":"定價決策應考慮增量成本與邊際收入的關係。"}]', 'phrasal verb'),
('infrastructure bond', '', '', '[{"en":"Pension funds seek infrastructure bonds for long-term stable income.","zh-TW":"養老基金尋求基礎設施債券以獲得長期穩定收入。"},{"en":"Infrastructure bonds often have government backing, making them lower risk.","zh-TW":"基礎設施債券通常有政府支持，使其風險較低。"}]', 'phrasal verb'),
('insolvency proceedings', '', '', '[{"en":"Creditors applied to court to commence insolvency proceedings.","zh-TW":"債權人向法院申請開始破產程序。"},{"en":"Insolvency proceedings determine how assets are distributed among creditors.","zh-TW":"破產程序確定資產如何在債權人之間分配。"}]', 'phrasal verb'),
('intracompany transaction', '', '', '[{"en":"Intracompany transactions must be eliminated when consolidating group accounts.","zh-TW":"在合並集團帳目時，公司內部交易必須被消除。"},{"en":"Transfer pricing rules apply to intracompany transactions across different tax jurisdictions.","zh-TW":"轉移定價規則適用於跨不同稅務司法管轄區的公司內部交易。"}]', 'phrasal verb'),
('inventory shrinkage', '', '', '[{"en":"Retail stores implement security measures to reduce inventory shrinkage.","zh-TW":"零售店實施安全措施以減少庫存短缺。"},{"en":"Annual stocktakes reveal the total inventory shrinkage over the year.","zh-TW":"年度盤點揭示了全年的庫存短缺總量。"}]', 'phrasal verb'),
('investment bank', '', '', '[{"en":"The company engaged an investment bank to manage its IPO process.","zh-TW":"公司聘請了投資銀行管理其IPO流程。"},{"en":"Investment banks advise on mergers, acquisitions, and capital raising.","zh-TW":"投資銀行就合併、收購和籌集資本提供建議。"}]', 'phrasal verb'),
('invoice approval', '', '', '[{"en":"A three-way match is used in invoice approval to verify accuracy.","zh-TW":"發票審批中使用三方匹配來驗證準確性。"},{"en":"Streamlining the invoice approval process reduces payment delays.","zh-TW":"簡化發票審批流程減少了付款延誤。"}]', 'phrasal verb'),
('issue price', '', '', '[{"en":"The bond''s issue price was 98% of face value, reflecting a 2% discount.","zh-TW":"債券的發行價格為面值的98%，反映了2%的折扣。"},{"en":"A high issue price signals strong investor demand for the new shares.","zh-TW":"高發行價格表明投資者對新股的強勁需求。"}]', 'phrasal verb'),
('joint tenancy', '', '', '[{"en":"Under joint tenancy, the surviving owner automatically inherits the other''s share.","zh-TW":"在聯合租賃下，在世的所有者自動繼承另一方的份額。"},{"en":"Joint tenancy is common for married couples purchasing residential property.","zh-TW":"聯合租賃對購買住宅房產的已婚夫婦很常見。"}]', 'phrasal verb'),
('key man insurance', '', '', '[{"en":"The company took out key man insurance on its founder and CEO.","zh-TW":"公司對其創始人和CEO購買了關鍵人物保險。"},{"en":"Key man insurance proceeds can fund succession planning or business continuity.","zh-TW":"關鍵人物保險賠付可用於資助繼任規劃或業務連續性。"}]', 'phrasal verb'),
('land valuation', '', '', '[{"en":"An independent land valuation is required before a bank approves a mortgage.","zh-TW":"銀行批准抵押貸款之前需要進行獨立的土地估值。"},{"en":"Land valuation considers location, zoning, and comparable sales.","zh-TW":"土地估值考慮位置、分區和可比銷售情況。"}]', 'phrasal verb'),
('launch date', '', '', '[{"en":"The launch date was moved forward to capture the holiday shopping season.","zh-TW":"發布日期提前以抓住假日購物季節。"},{"en":"Marketing materials must be ready two weeks before the launch date.","zh-TW":"行銷材料必須在發布日期前兩週準備就緒。"}]', 'phrasal verb'),
('lease renewal', '', '', '[{"en":"The tenant negotiated a lease renewal at a 5% reduced rental rate.","zh-TW":"租戶談判了以5%降低租金的租約續租。"},{"en":"Advance planning for lease renewal prevents gaps in business premises.","zh-TW":"提前規劃租約續租防止了業務場所的空缺。"}]', 'phrasal verb'),
('legal due diligence', '', '', '[{"en":"Legal due diligence identified three pending lawsuits not previously disclosed.","zh-TW":"法律盡職調查識別了三起先前未披露的未決訴訟。"},{"en":"Legal due diligence is a critical step in any merger or acquisition process.","zh-TW":"法律盡職調查是任何合併或收購流程中的關鍵步驟。"}]', 'phrasal verb'),
('letter of guarantee', '', '', '[{"en":"The contractor provided a letter of guarantee for the advance payment received.","zh-TW":"承包商為收到的預付款提供了保函。"},{"en":"A letter of guarantee protects the beneficiary if the applicant defaults.","zh-TW":"如果申請人違約，保函保護受益人。"}]', 'phrasal verb'),
('leverage buyout', '', '', '[{"en":"The private equity firm completed a leverage buyout using 70% debt financing.","zh-TW":"私募股權公司使用70%的債務融資完成了槓桿收購。"},{"en":"Leverage buyouts require strong cash flow to service the acquisition debt.","zh-TW":"槓桿收購需要強勁的現金流來償還收購債務。"}]', 'phrasal verb'),
('licensing fee', '', '', '[{"en":"The software company charges an annual licensing fee per user.","zh-TW":"軟件公司按每個用戶收取年度授權費。"},{"en":"A one-time licensing fee grants perpetual use rights to the buyer.","zh-TW":"一次性授權費向買方授予永久使用權。"}]', 'phrasal verb'),
('limited partnership', '', '', '[{"en":"The investment vehicle was structured as a limited partnership.","zh-TW":"投資工具被構建為有限合夥企業。"},{"en":"Limited partners have liability only up to their investment in the fund.","zh-TW":"有限合夥人的責任僅限於其在基金中的投資額。"}]', 'phrasal verb'),
('liquidation value', '', '', '[{"en":"The liquidation value of the company''s assets was significantly below book value.","zh-TW":"公司資產的清算價值顯著低於帳面價值。"},{"en":"Creditors assess liquidation value to estimate recovery in a default scenario.","zh-TW":"債權人評估清算價值以估計違約場景中的追回率。"}]', 'phrasal verb'),
('litigation risk', '', '', '[{"en":"The acquisition target had significant undisclosed litigation risk.","zh-TW":"收購目標有重大的未披露訴訟風險。"},{"en":"A well-drafted contract reduces litigation risk by addressing dispute resolution.","zh-TW":"起草良好的合約通過處理爭議解決減少了訴訟風險。"}]', 'phrasal verb'),
('loan origination', '', '', '[{"en":"Digital loan origination systems reduce approval times from weeks to hours.","zh-TW":"數字化貸款發放系統將審批時間從幾週縮短到幾小時。"},{"en":"Loan origination fees are charged as a percentage of the loan amount.","zh-TW":"貸款發放費用按貸款金額的百分比收取。"}]', 'phrasal verb'),
('lump sum contract', '', '', '[{"en":"The construction firm won a lump sum contract worth $5 million.","zh-TW":"建築公司贏得了價值500萬元的總額合約。"},{"en":"A lump sum contract places cost risk on the contractor to deliver within budget.","zh-TW":"總額合約將成本風險置於承包商身上，要求其在預算內交付。"}]', 'phrasal verb'),
('management consultant', '', '', '[{"en":"The management consultant recommended restructuring the supply chain.","zh-TW":"管理顧問建議重組供應鏈。"},{"en":"A management consultant brings external expertise and unbiased analysis.","zh-TW":"管理顧問帶來了外部專業知識和無偏見的分析。"}]', 'phrasal verb'),
('market liquidity', '', '', '[{"en":"High market liquidity allows investors to exit positions with minimal price impact.","zh-TW":"高市場流動性允許投資者以最小的價格影響退出倉位。"},{"en":"Market liquidity dried up during the financial crisis of 2008.","zh-TW":"在2008年金融危機期間，市場流動性枯竭了。"}]', 'phrasal verb'),
('market positioning', '', '', '[{"en":"Clear market positioning as a premium brand justified higher prices.","zh-TW":"作為高端品牌的清晰市場定位證明了較高價格的合理性。"},{"en":"Market positioning guides all branding and communication decisions.","zh-TW":"市場定位指導了所有品牌和傳播決策。"}]', 'phrasal verb'),
('market risk', '', '', '[{"en":"The portfolio manager hedged market risk using derivative instruments.","zh-TW":"投資組合管理人使用衍生品工具對沖市場風險。"},{"en":"Market risk includes equity risk, interest rate risk, and currency risk.","zh-TW":"市場風險包括股票風險、利率風險和貨幣風險。"}]', 'phrasal verb'),
('master budget', '', '', '[{"en":"The master budget was finalized after each department submitted its budget.","zh-TW":"各部門提交預算後，主預算得以定稿。"},{"en":"The master budget serves as the financial roadmap for the entire year.","zh-TW":"主預算為全年提供了財務路線圖。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('material information', '', '', '[{"en":"Listed companies must disclose material information without delay.","zh-TW":"上市公司必須毫不延遲地披露重大信息。"},{"en":"Withholding material information from investors may violate securities law.","zh-TW":"對投資者隱瞞重大信息可能違反證券法。"}]', 'phrasal verb'),
('materiality threshold', '', '', '[{"en":"The auditor set a materiality threshold of 5% of pre-tax income.","zh-TW":"審計師設定了稅前收入5%的重要性門檻。"},{"en":"Errors below the materiality threshold do not require correction.","zh-TW":"低於重要性門檻的錯誤不需要更正。"}]', 'phrasal verb'),
('monetary union', '', '', '[{"en":"Member states of a monetary union give up independent exchange rate policy.","zh-TW":"貨幣聯盟成員國放棄了獨立的匯率政策。"},{"en":"A monetary union reduces transaction costs in cross-border trade.","zh-TW":"貨幣聯盟降低了跨境貿易中的交易成本。"}]', 'phrasal verb'),
('multi-currency account', '', '', '[{"en":"A multi-currency account eliminates the need to convert currencies for each transaction.","zh-TW":"多幣種帳戶消除了每次交易轉換貨幣的需要。"},{"en":"Exporters use multi-currency accounts to manage foreign exchange efficiently.","zh-TW":"出口商使用多幣種帳戶高效管理外匯。"}]', 'phrasal verb'),
('multilateral agreement', '', '', '[{"en":"The multilateral agreement reduced trade tariffs among 12 member countries.","zh-TW":"多邊協議降低了12個成員國之間的貿易關稅。"},{"en":"A multilateral agreement requires consensus from all participating parties.","zh-TW":"多邊協議需要所有參與方的共識。"}]', 'phrasal verb'),
('comply with regulations', '', '', '[{"en":"All products must comply with safety regulations before sale.","zh-TW":"所有產品在銷售前必須遵守安全法規。"},{"en":"The factory was fined for failing to comply with environmental regulations.","zh-TW":"工廠因未能遵守環境法規而被罰款。"}]', 'phrasal verb'),
('deliverable outcome', '', '', '[{"en":"Each phase of the project has defined deliverable outcomes.","zh-TW":"項目的每個階段都有明確的交付成果。"},{"en":"Deliverable outcomes were reviewed by the client at each milestone.","zh-TW":"客戶在每個里程碑處審查了交付成果。"}]', 'phrasal verb'),
('demand forecast', '', '', '[{"en":"Accurate demand forecasting reduces overstock and out-of-stock situations.","zh-TW":"準確的需求預測減少了庫存過多和缺貨情況。"},{"en":"The demand forecast was adjusted after the competitor closed.","zh-TW":"競爭對手關閉後調整了需求預測。"}]', 'phrasal verb'),
('dispute resolution mechanism', '', '', '[{"en":"The contract includes a clear dispute resolution mechanism.","zh-TW":"合約包含明確的爭議解決機制。"},{"en":"Mediation is the preferred dispute resolution mechanism for commercial disputes.","zh-TW":"調解是商業糾紛的首選爭議解決機制。"}]', 'phrasal verb'),
('economic stimulus', '', '', '[{"en":"The government announced an economic stimulus package of 50 billion.","zh-TW":"政府宣佈了500億元的經濟刺激計劃。"},{"en":"Economic stimulus measures helped reduce unemployment.","zh-TW":"經濟刺激措施有助於降低失業率。"}]', 'phrasal verb'),
('embargo on imports', '', '', '[{"en":"The embargo on imports was lifted after diplomatic relations improved.","zh-TW":"隨著外交關係改善，進口禁令被解除了。"},{"en":"An embargo on imports was imposed to protect domestic producers.","zh-TW":"為保護國內生產商，進口禁令被實施了。"}]', 'phrasal verb'),
('equal opportunity', '', '', '[{"en":"The company is committed to being an equal opportunity employer.","zh-TW":"公司致力於成為機會平等的雇主。"},{"en":"Equal opportunity policies promote diversity in the workplace.","zh-TW":"機會平等政策促進了職場多樣性。"}]', 'phrasal verb'),
('excess inventory', '', '', '[{"en":"Excess inventory was sold at a discount to free up warehouse space.","zh-TW":"過剩庫存以折扣出售，以釋放倉庫空間。"},{"en":"Better demand forecasting helped reduce excess inventory by 40%.","zh-TW":"更好的需求預測有助於將過剩庫存減少40%。"}]', 'phrasal verb');
INSERT INTO grammar_topics (id, title, category, level, explanation_md) VALUES
(1, 'Present Simple vs Present Continuous', 'tense', 2, '現在簡單式用於習慣或事實（She works every day），現在進行式用於當下正在發生的動作（She is working now）。靜態動詞如 know、believe 不用進行式。商業英語中，簡單式描述職責，進行式描述當前專案。'),
(2, 'Past Simple vs Past Continuous', 'tense', 2, '過去簡單式描述已完成的過去動作，過去進行式描述過去某時刻正在進行的動作。兩者常搭配：進行式為背景，簡單式為插入動作。'),
(3, 'Present Perfect', 'tense', 3, '現在完成式（have/has + 過去分詞）連結過去動作與現在結果，常與 just、already、yet、ever、never、since、for 連用，不與 yesterday、last year 等明確過去時間連用。'),
(4, 'Present Perfect vs Past Simple', 'tense', 3, '現在完成式強調對現在的影響；過去簡單式描述已結束的特定事件。ago/yesterday/last year → 過去式；already/yet/just/since/for → 完成式。'),
(5, 'Past Perfect', 'tense', 3, '過去完成式（had + 過去分詞）描述過去某時間點之前已完成的動作，建立兩個過去事件的先後順序，常與 before、by the time、when、already 等連用。'),
(6, 'Future: will vs going to', 'tense', 2, 'will 用於臨時決定、承諾或預測；be going to 用於已計劃的意圖或根據證據的預測。兩者均可表未來，but 語用不同。'),
(7, 'Future Perfect and Future Continuous', 'tense', 4, '未來完成式（will have + p.p.）表示到未來某點前將完成的動作；未來進行式（will be + V-ing）表示未來某時刻正在進行的動作。兩者常用於商業時程規劃。'),
(8, 'Mixed Tenses', 'tense', 4, '混合時態練習要求根據語境選擇正確時態，是商業英語的重要能力。正確選擇時態能清楚傳達事件的時間順序和因果關係。'),
(9, 'Definite Article: the', 'article', 2, '定冠詞 the 用於雙方均知的特定事物、再次提及、獨一無二的事物及最高級前。商業英語中常見於職稱（the CEO）、特定文件（the report）、最高級（the best）。'),
(10, 'Indefinite Articles: a / an', 'article', 1, '不定冠詞 a 用在輔音音素前，an 用在母音音素前。注意判斷依據是發音不是拼字（如 an hour、an MBA）。用於首次提及或泛指某類別。'),
(11, 'Zero Article', 'article', 3, '零冠詞（不加冠詞）用於複數可數名詞泛稱、不可數名詞泛稱、專有名詞、及 go to work/by email 等固定搭配。避免在泛稱前加 the。'),
(12, 'Prepositions of Time: at/in/on', 'preposition', 2, 'at 用於精確時間（at 3 p.m.）；in 用於較長時段（in March、in 2024）；on 用於特定日期和星期（on Monday、on January 5th）。商業場合中正確使用避免誤解。'),
(13, 'Prepositions of Place: at/in/on', 'preposition', 2, 'at 表精確地點或功能性場所（at the reception）；in 表有邊界空間或地區（in the office）；on 表面或樓層（on the desk、on the third floor）。'),
(14, 'Prepositions of Movement', 'preposition', 2, '移動介系詞描述從一地到另一地的動作：to（去到）、into（進入）、out of（出去）、through（穿過）、across（橫越）、along（沿著）、past（經過）。'),
(15, 'Dependent Prepositions (adjective + prep)', 'preposition', 3, '形容詞與特定介系詞的固定搭配，如 responsible for、interested in、satisfied with、familiar with。必須記憶，不可任意替換。'),
(16, 'Dependent Prepositions (verb + prep)', 'preposition', 3, '動詞與特定介系詞的固定搭配，如 apply for、deal with、rely on、invest in。錯誤使用介系詞會造成誤解，需熟記常見搭配。'),
(17, 'Zero and First Conditional', 'conditional', 2, '零條件句（if + 現在式，現在式）表普遍事實；第一條件句（if + 現在式，will）表真實可能的未來情況。商業英語常用第一條件句提案或預測。'),
(18, 'Second Conditional', 'conditional', 3, '第二條件句（if + 過去式，would）表示假設或不太可能的情況。注意 if 子句中 be 動詞正式英語用 were，常用於假設討論和商業頭腦風暴。'),
(19, 'Third Conditional', 'conditional', 4, '第三條件句（if + had + p.p.，would have + p.p.）描述過去假設，用於反思決策。商業案例分析和後見之明討論中常見。'),
(20, 'Mixed Conditionals', 'conditional', 5, '混合條件句結合不同時態：最常見是 if + 過去完成式（過去假設），would + 原形（現在結果），如 If I had taken that job, I would be in London now。'),
(21, 'Modal: can / could', 'modal', 2, 'can 表現在的能力、許可或可能性；could 表過去能力、假設可能性或禮貌請求。商業英語中 could 比 can 更正式有禮貌。'),
(22, 'Modal: must / have to', 'modal', 2, 'must 表主觀強烈義務或邏輯推論；have to 表外在客觀規定。must not 表禁止；do not have to 表不必要（不是禁止）。'),
(23, 'Modal: should / ought to', 'modal', 2, 'should 和 ought to 表建議或期望，should 更口語常用。商業英語中 should 常見於建議、指南、政策手冊中。'),
(24, 'Modal: may / might', 'modal', 3, 'may 和 might 都表可能性，might 確定性略低。may 也可表正式許可。商業報告中用於謹慎預測，避免過於武斷。'),
(25, 'Modal: would', 'modal', 3, 'would 多用法：過去習慣、禮貌請求（Would you...）、假設（I would accept）、提供建議（I would recommend）。商業溝通中是最禮貌的情態動詞。'),
(26, 'Modal Perfect: should have / could have / would have', 'modal', 4, '情態完成式談論過去不同的可能：should have（應該做但沒做，遺憾/批評），could have（本可以，可能性），would have（假設結果）。'),
(27, 'Passive Voice: Simple Tenses', 'passive', 3, '被動語態（am/is/are/was/were + p.p.）強調動作接受者，廣泛用於商業正式文件。當行為者不重要或不明確時特別適用。'),
(28, 'Passive Voice: Perfect Tenses', 'passive', 4, '完成被動式：現在完成被動（have/has been + p.p.）和過去完成被動（had been + p.p.）。商業報告中用於說明已完成的程序，語氣正式客觀。'),
(29, 'Passive Voice: Modal Verbs', 'passive', 4, '情態被動（modal + be + p.p.）廣泛用於商業政策和通知：must be submitted、should be reviewed、will be sent、can be accessed。'),
(30, 'Causative Have/Get', 'passive', 4, '使役結構：have/get something done（安排別人做）；have someone do（主動命令）；get someone to do（說服/促使）。常用於委託、外包描述。'),
(31, 'Reported Speech: Statements', 'reported speech', 3, '間接引語將直接引語轉為第三人稱，動詞時態後移，代名詞和時間副詞也需調整。商業會議記錄和轉述客戶意見時常用。'),
(32, 'Reported Speech: Questions', 'reported speech', 3, '間接問句語序是陳述句序，no 不用問號。yes/no 問句用 if/whether 引導。如：She asked what the deadline was；He asked if the report was ready。'),
(33, 'Reported Speech: Commands', 'reported speech', 3, '間接命令句：tell/ask/order/advise + 受詞 + to do（肯定）；tell + 受詞 + not to do（否定）。'),
(34, 'Backshift in Reported Speech', 'reported speech', 4, '間接引語時態後移規則：現在→過去，過去→過去完成，will→would，can→could，may→might。時間副詞：now→then，today→that day，tomorrow→the following day，here→there。'),
(35, 'Defining Relative Clauses', 'relative clause', 3, '限定性關係子句提供識別被修飾名詞所必需的資訊，不用逗號，可用 who（人）、which（物）、that（人或物）、whose（所有格）。'),
(36, 'Non-defining Relative Clauses', 'relative clause', 4, '非限定性關係子句提供額外（非必要）資訊，用逗號隔開，不可用 that，只用 who/which/whose/where/when。'),
(37, 'Relative Pronouns: who/which/that/whose', 'relative clause', 3, 'who 指人（主格/受格），which 指物（限定/非限定），that 指人或物（只限限定子句），whose 表所有格（人或物）。'),
(38, 'Gerund vs Infinitive after Verbs', 'gerund/infinitive', 3, '某些動詞後接動名詞（enjoy/finish/suggest/consider/avoid），某些後接不定詞（want/decide/agree/plan/refuse），有些兩者皆可但意思可能不同（stop/remember/try）。'),
(39, 'Gerund as Subject', 'gerund/infinitive', 2, '動名詞可作句子主語，如 Managing a team requires strong communication skills。這種結構在商業政策說明、工作描述中非常常見。'),
(40, 'Infinitive of Purpose', 'gerund/infinitive', 2, '不定詞表目的（to do），更正式用 in order to 或 so as to。商業英語中清楚說明行動目的，常見於策略計劃和提案。'),
(41, 'Verb + Object + Infinitive', 'gerund/infinitive', 3, '某些動詞後接受詞再接不定詞：want/ask/advise/require/expect/allow/encourage + 受詞 + to do。商業指示和委託中大量使用。'),
(42, 'Comparative Adjectives', 'comparison', 2, '比較級：單音節 + -er（faster）；多音節 + more（more efficient）；不規則：good→better，bad→worse，far→farther/further。'),
(43, 'Superlative Adjectives', 'comparison', 2, '最高級：單音節 + the -est（the fastest）；多音節 + the most（the most innovative）；不規則：good→the best，bad→the worst。'),
(44, 'Comparing with as...as', 'comparison', 2, 'as + 形容詞/副詞 + as 表相等；not as...as 表不如；the same...as 表相同；as much/many...as 表數量相等。'),
(45, 'Double Comparatives', 'comparison', 4, '雙重比較結構 the + 比較級 + the + 比較級，表示正比或反比關係。常見於商業策略討論，如 The more we invest, the higher the returns。'),
(46, 'Adverbial Clauses of Time', 'clause', 3, '時間副詞子句由 when、while、as soon as、before、after、until、by the time 等引導，表示動作發生的時間關係。'),
(47, 'Adverbial Clauses of Reason', 'clause', 3, '原因副詞子句由 because、since、as、now that 等引導，解釋動作的原因。商業英語中常用於說明決策理由。'),
(48, 'Adverbial Clauses of Contrast', 'clause', 3, '對比副詞子句由 although、even though、while、whereas 等引導，承認一個事實同時提出相反情況。商業英語中用於客觀分析。'),
(49, 'Adverbial Clauses of Result', 'clause', 3, '結果副詞子句由 so...that 或 such...that 引導，表示原因導致的結果。如 The presentation was so compelling that the client signed immediately。'),
(50, 'Noun Clauses', 'clause', 4, '名詞子句充當名詞功能（主語、受語或補語），常由 that、whether、what、how、why、who 等引導。商業英語中常用於表達觀點和轉述資訊。');
INSERT INTO grammar_topics (id, title, category, level, explanation_md) VALUES
(51, 'Coordinating Conjunctions: FANBOYS', 'conjunction', 2, 'FANBOYS（for、and、nor、but、or、yet、so）連接對等成分。商業英語常用 and（增加）、but（對比）、so（結果）、or（選擇）。'),
(52, 'Subordinating Conjunctions', 'conjunction', 3, '從屬連接詞引導從屬子句，包括時間（when）、原因（because）、條件（if/unless）、對比（although）等，建立複雜的邏輯關係。'),
(53, 'Correlative Conjunctions: either...or / neither...nor', 'conjunction', 3, '相關連接詞成對使用：either...or（兩者之一）；neither...nor（兩者都不）；both...and（兩者都）；not only...but also（不只...而且）。主謂一致依就近原則。'),
(54, 'Basic Sentence Structure (SVO)', 'word order', 1, '英語基本結構是主語-動詞-受語（SVO）。時間和地點副詞通常置句尾。修飾語放被修飾詞附近。這是所有英語寫作的基礎。'),
(55, 'Adverb Placement', 'word order', 3, '頻率副詞（always/often/never）置 be 後、主要動詞前；程度副詞（very/quite）置形容詞/副詞前；時間/地點副詞通常句尾。'),
(56, 'Inversion after Negative Adverbials', 'word order', 5, '否定副詞位於句首時需主謂倒裝：Never have we seen...；Not only did we...；Rarely does...；Hardly had...。常見於正式商業演講和高品質寫作。'),
(57, 'Quantifiers: some / any / no', 'determiner', 2, 'some 用於肯定句和期望肯定答案的疑問句；any 用於否定句和一般疑問句；no = not any（語氣更強）。'),
(58, 'Quantifiers: much / many / a lot of', 'determiner', 2, 'much + 不可數名詞（much time）；many + 可數名詞（many clients）；a lot of 兩者皆可，口語化。正式書面英語偏好 much/many。'),
(59, 'Quantifiers: few / little / a few / a little', 'determiner', 3, 'few/little 表幾乎沒有（消極）；a few/a little 表有一些（積極）。few/a few 用於可數名詞；little/a little 用於不可數名詞。'),
(60, 'Each / Every / All', 'determiner', 3, 'each 強調個別性（each employee）；every 強調整體的每一個（every department）；all 表全體（all staff）。each/every 接單數動詞，all 接複數動詞。'),
(61, 'Reflexive Pronouns', 'pronoun', 2, '反身代名詞（myself、yourself、himself、herself、itself、ourselves、yourselves、themselves）用於反身動作或強調（親自）。'),
(62, 'Indefinite Pronouns: someone/anyone/no one', 'pronoun', 2, 'someone/somebody 肯定句；anyone/anybody 疑問/否定句；no one/nobody 否定意義。對應 something/anything/nothing；somewhere/anywhere/nowhere。'),
(63, 'Countable and Uncountable Nouns', 'noun', 2, '可數名詞有複數（report→reports）；不可數名詞無複數（information、advice、equipment、furniture、progress、research、knowledge、news）。'),
(64, 'Compound Nouns', 'noun', 3, '複合名詞由兩個或更多詞組成，如 market research、software update、customer service。重音通常在第一個詞。書寫形式有分開、連字號或合一詞等。'),
(65, 'Order of Adjectives', 'adjective', 3, '形容詞排列順序：數量→意見→尺寸→年齡→形狀→顏色→來源→材質→目的。如 a small modern Japanese conference room。'),
(66, 'Participial Adjectives: -ed vs -ing', 'adjective', 3, '-ed 形容詞描述人的感受（I''m satisfied）；-ing 形容詞描述造成感受的事物（The results are satisfying）。混用是常見錯誤。'),
(67, 'Adverbs of Frequency', 'adverb', 2, '頻率副詞依次：always→usually/generally→often/frequently→sometimes/occasionally→rarely/seldom→never。置 be 後、主要動詞前。'),
(68, 'Adverbs of Degree', 'adverb', 3, '程度副詞強化或弱化程度：very/extremely/highly（非常）、quite/fairly/rather（相當）、somewhat/slightly（稍微）、barely/hardly（幾乎不）。'),
(69, 'Connecting Adverbs', 'adverb', 3, '連接副詞（conjunctive adverbs）連接兩個獨立子句，通常前有分號或句號後有逗號：however、therefore、moreover、furthermore、nevertheless、consequently、meanwhile。'),
(70, 'Cleft Sentences: It is...that', 'emphasis', 4, '分裂句 It is/was...that 強調句中特定成分。如 It was the CEO who approved it（強調主語）；It is the price that concerns us（強調受語）。'),
(71, 'Emphatic Do', 'emphasis', 4, '強調助動詞 do/does/did 用於強調肯定動詞，反駁懷疑或加強肯定語氣，如 We do appreciate your feedback。'),
(72, 'Subjunctive Mood', 'subjunctive', 5, '虛擬語氣用於建議/要求動詞（suggest/recommend/insist/require/demand）後的 that 子句，動詞用原形。It is essential/important/necessary + that + 原形。'),
(73, 'Wishes and Regrets: wish / if only', 'subjunctive', 4, 'wish + 過去式表現在的願望；wish + 過去完成式表過去的遺憾；wish + would 表對他人行為的期望；if only 語氣更強。'),
(74, 'Present Participle Clauses', 'participle clause', 4, '現在分詞子句（-ing 子句）表示同時進行或原因，取代副詞子句使文章更簡潔。如 Knowing the deadline, she worked overtime。'),
(75, 'Past Participle Clauses', 'participle clause', 4, '過去分詞子句（-ed 子句）通常表被動的完成動作，取代 when/after/because + passive。如 Reviewed by the team, the report was approved。'),
(76, 'Reduced Relative Clauses', 'participle clause', 4, '關係子句縮減：主動 → 現在分詞（the employee who manages = the employee managing）；被動 → 過去分詞（the report that was submitted = the report submitted）。'),
(77, 'Formal vs Informal Register', 'register', 3, '正式英語：完整形式（I am writing）、正式詞彙（assist/commence/enquire）、被動語態、避免縮寫。非正式：縮寫、口語詞彙。根據語境調整語體。'),
(78, 'Hedging Language', 'register', 4, '模糊限制語軟化陳述，表達不確定性或保持禮貌：It seems/appears that、This might/may、It would appear that、Apparently、Somewhat。廣泛用於商業分析和外交溝通。'),
(79, 'Nominalization', 'register', 4, '名詞化將動詞/形容詞轉為名詞，使文體更正式客觀。decide→decision、improve→improvement、analyze→analysis、discuss→discussion。'),
(80, 'Formal Writing: Passive and Impersonal', 'register', 4, '正式商業寫作使用被動語態（It has been decided）和非人稱結構（It is important to note that）保持客觀性，廣泛用於商業報告、提案和官方通知。'),
(81, 'Colons and Semicolons', 'punctuation', 3, '冒號（:）引出列表、解釋或強調；分號（;）連接兩個獨立但緊密相關的子句，代替句號。正確使用展現書面語言精確性。'),
(82, 'Apostrophes', 'punctuation', 2, '撇號用於縮寫（it''s = it is；we''re = we are）和所有格（the company''s policy；the managers'' reports）。注意 its（所有格）vs it''s（it is）。'),
(83, 'TOEIC: Part 5 Vocabulary in Context', 'TOEIC', 3, 'TOEIC Part 5 根據上下文選擇正確詞彙。策略：先讀完整句子，注意關鍵詞和搭配，用消去法。廣泛閱讀商業文章是提升詞彙的最佳方法。'),
(84, 'TOEIC: Part 5 Grammar Focus', 'TOEIC', 3, 'TOEIC Part 5 語法題涵蓋時態、詞類、介系詞等，需快速準確判斷。考試策略：識別空格的詞性，排除明顯錯誤，注意主謂一致。'),
(85, 'TOEIC: Part 6 Text Completion', 'TOEIC', 3, 'TOEIC Part 6 需根據整段上下文選擇正確詞彙、時態或句子。理解篇章邏輯和連貫性是關鍵，要看前後文選擇最合適的填空。'),
(86, 'TOEIC: Business Vocabulary I', 'TOEIC', 2, 'TOEIC 商業核心詞彙：合約（contract/agreement）、付款（invoice/receipt）、出貨（shipment/dispatch）、人資（recruitment/candidate）等。'),
(87, 'TOEIC: Business Vocabulary II', 'TOEIC', 2, 'TOEIC 商業詞彙進階：財務（fiscal/revenue/deficit）、策略（merger/acquisition/restructuring）、客戶關係（retention/satisfaction/complaint）等。'),
(88, 'TOEIC: Business Vocabulary III', 'TOEIC', 3, 'TOEIC 進階商業詞彙：談判（negotiate/concession）、組織（hierarchy/delegate）、數位商業（platform/scalable/disruptive）等。'),
(89, 'TOEIC: Part 7 Reading Comprehension Strategies', 'TOEIC', 3, 'TOEIC Part 7 需快速掌握文章主旨、推斷資訊及理解細節。常見題型：主旨題、細節題、詞義題、推斷題。本主題練習商業文件閱讀理解。'),
(90, 'TOEIC: Subject-Verb Agreement', 'TOEIC', 2, '主謂一致是 TOEIC 高頻考點：集合名詞、either/neither、not only...but also、there is/are、每一/all of。'),
(91, 'TOEIC: Preposition and Phrasal Verb Collocations', 'TOEIC', 3, 'TOEIC 常考介系詞固定搭配和片語動詞，如 look forward to、in charge of、deal with、carry out、put off。'),
(92, 'TOEIC: Word Forms', 'TOEIC', 3, 'TOEIC 詞形變化題考驗能否識別空格需要的詞性（名詞/動詞/形容詞/副詞），需熟悉常見詞尾：-tion、-ment、-al、-ous、-ly、-ize 等。'),
(93, 'TOEIC: Sentence Structure Errors', 'TOEIC', 3, '辨識常見語法錯誤：主謂不一致、時態錯誤、多餘詞、遺漏詞等。TOEIC Part 5 需快速識別並選出正確選項。'),
(94, 'Tag Questions', 'grammar', 3, '附加問句（疑問附加語）：陳述句用正附加，疑問句用負附加（She is here, isn''t she? / He isn''t coming, is he?）。情態動詞、完成式、被動式均有對應附加問句。'),
(95, 'Conditionals: unless / provided that / as long as', 'conditional', 3, 'unless = if not（除非）；provided (that) = on condition that（前提是）；as long as = if（只要）。這三個詞都引導條件子句，是 if 的重要替代表達。'),
(96, 'Present Perfect Continuous', 'tense', 4, '現在完成進行式（have/has been + V-ing）強調從過去持續到現在的動作，常與 for/since/all day/recently 連用，強調動作的持續性。'),
(97, 'Reported Speech: No Backshift Exceptions', 'reported speech', 4, '當報告的是普遍事實、科學真理、仍為真的情況，或報告者認為時態不需後移時，時態不必後移。正式學術和新聞英語中常見此現象。'),
(98, 'Sentence Connectors: Listing and Addition', 'conjunction', 3, '列舉和補充連接詞：firstly/secondly/finally（列舉順序）；in addition/furthermore/moreover（補充）；as well as/also/too（也）；what is more（更重要的是）。'),
(99, 'Sentence Connectors: Contrast and Concession', 'conjunction', 3, '對比讓步連接詞：however/nevertheless（然而）；on the other hand（另一方面）；by contrast（相比之下）；in spite of this（儘管如此）；even so（即便如此）。'),
(100, 'Question Forms', 'grammar', 2, '疑問句種類：Yes/No 問句（使用助動詞倒裝）；Wh- 問句（疑問詞 + 助動詞倒裝）；間接問句（陳述語序）；主語問句（疑問詞作主語，無倒裝）。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(1, 'multiple_choice', 'She _____ in the marketing department.', '["is working","work","working","works"]', 'works', 'works 用現在簡單式描述固定職責。'),
(1, 'multiple_choice', 'They _____ on a new product right now.', '["worked","works","are working","work"]', 'are working', 'right now 需用現在進行式 are working。'),
(1, 'multiple_choice', 'He usually _____ to the office by 9 a.m.', '["has arrived","is arriving","arrive","arrives"]', 'arrives', 'usually 搭配現在簡單式 arrives。'),
(1, 'multiple_choice', 'We _____ our quarterly report this week.', '["prepared","are preparing","prepare","prepares"]', 'are preparing', 'this week 暫時性，are preparing 正確。'),
(1, 'multiple_choice', 'The CEO _____ a speech at the conference tomorrow.', '["gave","give","is giving","gives"]', 'is giving', '已安排的未來，is giving 正確。'),
(1, 'multiple_choice', 'Our team _____ five days a week.', '["are working","work","works","is working"]', 'works', 'five days a week 頻率，works 三單正確。'),
(1, 'fill_blank', 'Listen! The manager _____ (speak) to the client right now.', NULL, 'is speaking', 'Listen! 表當下進行，is speaking。'),
(1, 'fill_blank', 'She always _____ (check) her emails before the meeting.', NULL, 'checks', 'always 搭配簡單式，checks 三單。'),
(1, 'multiple_choice', 'I _____ the new software is very efficient.', '["thinks","think","am thinking","thought"]', 'think', 'think 靜態動詞，不用進行式。'),
(1, 'multiple_choice', 'The sales figures _____ every quarter.', '["increases","increase","increased","are increasing"]', 'increase', 'every quarter 固定規律，簡單式 increase。'),
(1, 'fill_blank', 'Sales _____ (rise) steadily this quarter.', NULL, 'are rising', 'this quarter 當下趨勢，are rising。'),
(1, 'transform', 'The company reviews budgets quarterly. (Rewrite using: reviews)', NULL, 'The company reviews its annual budget every quarter.', '現在簡單式 reviews 表定期政策。'),
(1, 'multiple_choice', 'She _____ at three different locations this month.', '["works","worked","work","is working"]', 'is working', 'this month 暫時性，is working 正確。'),
(1, 'multiple_choice', 'We _____ international clients on a regular basis.', '["served","serve","are serving","serves"]', 'serve', 'on a regular basis 固定習慣，serve 複數主詞。'),
(1, 'fill_blank', 'Please be quiet. I _____ (concentrate) on this report.', NULL, 'am concentrating', '當下正在進行，am concentrating。'),
(1, 'multiple_choice', 'The training program _____ for new hires every six months.', '["run","runs","ran","is running"]', 'runs', 'every six months 固定週期，runs 三單。'),
(1, 'multiple_choice', 'Look at those clouds — it _____ to rain.', '["went","go","is going","goes"]', 'is going', '根據眼前跡象，is going to rain。'),
(1, 'fill_blank', 'Profits _____ (grow) faster than expected this year.', NULL, 'are growing', 'this year 當前進行趨勢，are growing。'),
(1, 'multiple_choice', 'She _____ in charge of client relations.', '["be","was","are","is"]', 'is', 'is 現在式三單，描述當前職責。'),
(1, 'multiple_choice', 'The board _____ three times a year.', '["is meeting","meets","met","meet"]', 'meets', 'three times a year 頻率，簡單式 meets。'),
(2, 'multiple_choice', 'She _____ a presentation when the power went out.', '["was giving","gives","had given","gave"]', 'was giving', '過去進行式描述背景動作 was giving；when 引入插入動作。'),
(2, 'multiple_choice', 'The team _____ the project last Friday.', '["completes","was completing","has completed","completed"]', 'completed', 'last Friday 明確時間點，過去簡單式 completed。'),
(2, 'multiple_choice', 'While I _____ the contract, my boss called.', '["had reviewed","reviewed","was reviewing","review"]', 'was reviewing', 'while 引導背景進行式 was reviewing。'),
(2, 'multiple_choice', 'He _____ the report at 10 a.m. yesterday.', '["wrote","had written","was writing","writes"]', 'was writing', 'at 10 a.m. yesterday 指過去時刻進行中，was writing。'),
(2, 'multiple_choice', 'We _____ the deal in 2022.', '["were finalizing","finalized","finalize","had finalized"]', 'finalized', 'in 2022 完成時間點，過去簡單式 finalized。'),
(2, 'fill_blank', 'When the CEO entered, everyone _____ (stand) up.', NULL, 'stood', 'stand up 是即時反應，過去簡單式 stood。'),
(2, 'fill_blank', 'They _____ (negotiate) for two hours when the client left.', NULL, 'were negotiating', '背景動作用過去進行式 were negotiating。'),
(2, 'multiple_choice', 'I _____ in Tokyo when I received the news.', '["have attended","attend","was attending","attended"]', 'was attending', '背景進行式 was attending，插入 received。'),
(2, 'multiple_choice', 'The system _____ down three times last week.', '["went","was going","goes","had gone"]', 'went', 'last week 加次數，過去簡單式 went。'),
(2, 'transform', 'She talked to the client. At the same time she reviewed the doc. (Use: while)', NULL, 'While she was talking to the client, she reviewed the document.', 'while 引導背景進行式，主句過去簡單式。'),
(2, 'fill_blank', 'He _____ (travel) to Singapore when his flight got delayed.', NULL, 'was travelling', '背景動作用過去進行式 was travelling。'),
(2, 'multiple_choice', 'The review _____ three hours.', '["was lasting","has lasted","lasted","lasts"]', 'lasted', '過去簡單式 lasted 描述完整持續時間。'),
(2, 'multiple_choice', 'What _____ you _____ at 3 p.m. Thursday?', '["did / do","have / done","do / doing","were / doing"]', 'were / doing', 'at 3 p.m. 過去時刻，過去進行式疑問句。'),
(2, 'fill_blank', 'As I _____ (prepare) the slides, I noticed an error.', NULL, 'was preparing', 'As 引導背景動作，過去進行式 was preparing。'),
(2, 'multiple_choice', 'The new policy _____ effect in January last year.', '["was taking","takes","took","had taken"]', 'took', '明確時間，過去簡單式 took effect。'),
(2, 'multiple_choice', 'She _____ the file when her computer crashed.', '["updates","had updated","updated","was updating"]', 'was updating', '背景 was updating，插入 crashed。'),
(2, 'fill_blank', 'The team _____ (celebrate) when they heard the news.', NULL, 'was celebrating', '背景動作用過去進行式 was celebrating。'),
(2, 'multiple_choice', 'The conference _____ for three days.', '["lasts","lasted","was lasting","has lasted"]', 'lasted', '過去簡單式 lasted 描述完成持續。'),
(2, 'transform', 'He worked at the office. Then his phone rang. (Use: was working when)', NULL, 'He was working at the office when his phone rang.', 'was working 背景進行式，when 引入插入動作。'),
(2, 'multiple_choice', 'I _____ the client when my manager interrupted.', '["have called","was calling","called","call"]', 'was calling', '背景 was calling，插入 interrupted。'),
(3, 'multiple_choice', 'We _____ the new system last month.', '["were implementing","implement","implemented","have implemented"]', 'implemented', 'last month 明確過去，過去簡單式 implemented。'),
(3, 'multiple_choice', 'The company _____ its revenue by 20% this year.', '["increase","increased","has increased","was increasing"]', 'has increased', 'this year 到目前，現在完成式 has increased。'),
(3, 'fill_blank', 'She _____ (work) here for five years.', NULL, 'has worked', 'for five years 持續到現在，has worked。'),
(3, 'multiple_choice', 'Have you _____ the client''s requirements?', '["review","were reviewing","reviewed","reviewing"]', 'reviewed', 'Have you + 過去分詞，現在完成式疑問句。'),
(3, 'fill_blank', 'Profits _____ (rise) steadily since the restructuring.', NULL, 'have risen', 'since 搭配現在完成式 have risen。'),
(3, 'multiple_choice', 'This is the best quarter our company _____.', '["was ever having","ever had","had ever","has ever had"]', 'has ever had', 'ever 搭配最高級使用現在完成式。'),
(3, 'transform', 'We launched the product. It is now in 30 markets. (Use: have launched)', NULL, 'We have launched the product and it is now in 30 markets.', '現在完成式連結過去行動與現在狀態。'),
(3, 'multiple_choice', 'They _____ their headquarters to Singapore.', '["move","were moving","have moved","moved"]', 'have moved', '強調結果，現在完成式 have moved。'),
(3, 'fill_blank', 'The manager _____ just _____ (return) from the trade fair.', NULL, 'has / returned', 'just 搭配現在完成式。'),
(3, 'multiple_choice', 'We _____ this client for over ten years.', '["are serving","served","have served","serve"]', 'have served', 'for over ten years 持續到現在，have served。');